import sys
import math

def find_array(X, d):
    if d == 1:
        if X == 1:
            return [1]
        else:
            return -1
    n = int(math.log2(X + 1))
    if 2 ** n - 1 < X:
        n += 1
    if 2 ** n - 1 > X:
        return -1
    array = [1]
    for i in range(1, n):
        array.append(array[-1] + d)
    return array

def main():
    X, d = map(int, sys.stdin.read().strip().split())
    result = find_array(X, d)
    if result == -1:
        print(-1)
    else:
        print(len(result))
        print(" ".join(map(str, result)))

main()
